# Parse out the 9 individual reviews
lines = context.strip().split('\n')
reviews = []
current_review = []

for line in lines:
    if line.startswith('Date:') and current_review:
        reviews.append('\n'.join(current_review))
        current_review = [line]
    elif line.startswith('Date:'):
        current_review = [line]
    elif line.startswith('Recall:') or line.startswith('In the above'):
        break
    else:
        current_review.append(line)

if current_review:
    reviews.append('\n'.join(current_review))

print(f"Extracted {len(reviews)} reviews")

# Create classification prompts
prompts = []
for i, review in enumerate(reviews):
    prompt = f"""Review: {review[:800]}

Classify this movie review as either 'positive' or 'negative'. 
Respond with ONLY one word: positive or negative."""
    prompts.append(prompt)

print(f"Created {len(prompts)} prompts")
print(f"First prompt preview: {prompts[0][:300]}...")
